import{_ as e,o as l,c as d,a2 as t}from"./chunks/framework.BUwdTBzS.js";const h=JSON.parse('{"title":"AI行为规范","description":"","frontmatter":{"title":"AI行为规范"},"headers":[],"relativePath":"rules/AI行为规范.md","filePath":"rules/AI行为规范.md","lastUpdated":null}'),c={name:"rules/AI行为规范.md"};function r(a,o,s,i,n,u){return l(),d("div",null,[...o[0]||(o[0]=[t('<blockquote><p>📄 本页由源文件 <code>rules/AI行为规范.mdc</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="ai行为规范" tabindex="-1">AI行为规范 <a class="header-anchor" href="#ai行为规范" aria-label="Permalink to &quot;AI行为规范&quot;">​</a></h1><p>管理 AI 的工作方式和自我管理行为，与代码规范、安全红线等职责分离。</p><hr><h2 id="skill-触发检查-最高优先级" tabindex="-1">Skill 触发检查（最高优先级） <a class="header-anchor" href="#skill-触发检查-最高优先级" aria-label="Permalink to &quot;Skill 触发检查（最高优先级）&quot;">​</a></h2><blockquote><p>收到用户消息后，<strong>第一步</strong>静默执行触发检查。关键词定义及完整规则见 <strong>dev-flow SKILL.md 触发规则章节</strong>（权威来源）。</p></blockquote><h3 id="dev-flow-触发规则-2026-06-01-改版-仅显式命令触发" tabindex="-1">dev-flow 触发规则（2026-06-01 改版：仅显式命令触发） <a class="header-anchor" href="#dev-flow-触发规则-2026-06-01-改版-仅显式命令触发" aria-label="Permalink to &quot;dev-flow 触发规则（2026-06-01 改版：仅显式命令触发）&quot;">​</a></h3><blockquote><p><strong>核心原则</strong>：dev-flow 触发权交给用户，AI 不得基于关键词主观判断而自动触发。</p></blockquote><p><strong>触发判定（4 步）</strong>：</p><ol><li><strong>显式命令</strong> → 命中即 <code>use_skill(&#39;dev-flow&#39;)</code>： <ul><li><code>dev-flow</code> / <code>dev:</code> / <code>/dev-flow</code>（统一入口）</li><li><code>dev:status</code> / <code>dev:st</code> / <code>dev:kb</code> / <code>dev:k</code> / <code>dev:metrics</code> / <code>dev:m</code> / <code>dev:onboard</code> / <code>dev:ob</code></li><li><code>--micro</code> / <code>--fast</code>（修饰命令）</li></ul></li><li><strong>活跃流程恢复</strong> → <code>~/.codebuddy/working-context/.active-flows/</code> 下存在 <code>.flow</code> 文件 <strong>且</strong> 用户消息与该流程的 <code>match_keywords</code> / <code>brief</code> 相关 → <code>use_skill(&#39;dev-flow&#39;)</code>（v3 智能恢复网关）；不相关时不触发</li><li><strong>关键词建议（不自动触发）</strong> → 检测到开发意图关键词（<code>修复</code> / <code>优化</code> / <code>新需求</code> / <code>提测反馈</code> / 任务平台链接 / 设计稿链接）时，<strong>在回复中主动建议</strong> <code>dev-flow</code> 命令（若评估满足 <code>--micro</code> 准入条件（≤3 文件、≤10 行/文件、用户已指明精确位置），则优先推荐 <code>dev-flow --micro</code>；条件权威源 → <code>skills/dev-flow/references/mode-matrix.md</code> §三bis），等待用户决策；<strong>严禁自动调用</strong> <code>use_skill(&#39;dev-flow&#39;)</code></li><li><strong>未命中以上</strong> → 普通对话</li></ol><p><strong>优先级</strong>：显式 dev-flow 命令 &gt; 活跃流程恢复（相关时） &gt; issue-trace（详见 <code>skills/issue-trace/SKILL.md</code>） &gt; 普通对话（含开发意图建议）</p><p><strong>强执行</strong>：触发后步骤不可跳过；未触发时禁止操作 <code>~/.codebuddy/working-context/</code>（<code>.active-flows/</code> 存在性检测除外），误判创建则主动清理</p><h2 id="dev-flow-工具门禁-红牌-15" tabindex="-1">dev-flow 工具门禁（红牌 #15） <a class="header-anchor" href="#dev-flow-工具门禁-红牌-15" aria-label="Permalink to &quot;dev-flow 工具门禁（红牌 #15）&quot;">​</a></h2><blockquote><p>dev-flow 激活期间，每个 tool call 前自检：当前步骤是否允许该工具。不允许 → 🔴 红牌 #15 立即停止。 权威配置：<code>skills/dev-flow/config/gates.yaml</code> §<code>tool_gates</code>（phases 定义白名单，mode_exemptions 定义模式豁免）。 核心禁令：阶段 0 禁写代码+禁主动搜索源码；步骤 1-4 禁写代码+禁写操作命令。逃生舱：用户显式说&quot;直接改&quot;。</p></blockquote><h2 id="dev-flow-子节点引用规范-强制" tabindex="-1">dev-flow 子节点引用规范（强制） <a class="header-anchor" href="#dev-flow-子节点引用规范-强制" aria-label="Permalink to &quot;dev-flow 子节点引用规范（强制）&quot;">​</a></h2><p>引用 dev-flow 步骤内子节点（如步骤 4 的环节、步骤 6 的 6A、步骤 5.5 的 a/b/c 等）时，<strong>面向用户的输出</strong>必须带语义名：</p><ul><li>❌ 禁止裸编号：<code>步骤 4 阶段 3</code> / <code>6A</code> / <code>5.5b</code> / <code>H.3+</code> / <code>10.3.5</code> 单独出现</li><li>❌ 禁止用「阶段 N」指代步骤内部子节点（顶层「阶段 0/0.5」除外，永久保留）</li><li>✅ 必须用「编号 · 语义名」：<code>步骤 4 · 文档决策（环节 3/4）</code> / <code>步骤 6A · 自动化验证</code> / <code>步骤 5.5a · L1 代码审查</code></li></ul><blockquote><p>📌 各步骤的语义名清单 + 全步骤口播标准 + 未来新增子节点命名守则 → 按需加载 <code>skills/dev-flow/references/gate-validator.md</code> §「步骤内子环节引用规范门控」</p></blockquote><h2 id="主动文档同步弹框提醒-dev-flow-激活期间" tabindex="-1">主动文档同步弹框提醒（dev-flow 激活期间） <a class="header-anchor" href="#主动文档同步弹框提醒-dev-flow-激活期间" aria-label="Permalink to &quot;主动文档同步弹框提醒（dev-flow 激活期间）&quot;">​</a></h2><blockquote><p>📌 弹框场景、物理层契约、防退化条款、执行规则 → <code>skills/dev-flow/references/in-flow-sync.md</code> §1.2。</p></blockquote><h2 id="上下文管理" tabindex="-1">上下文管理 <a class="header-anchor" href="#上下文管理" aria-label="Permalink to &quot;上下文管理&quot;">​</a></h2><p><strong>批量操作保护</strong>（≥3 个文件）：先用 <code>todo_write</code> 列清单，逐个执行、逐个汇报</p><p><strong>上下文精简</strong>：</p><ul><li>大量工具结果 → 提取关键信息，避免全文保留</li><li>长文件 → 关键区域 + 结构概要</li><li>已完成步骤 → 仅保留结论</li></ul><h2 id="输出格式规范" tabindex="-1">输出格式规范 <a class="header-anchor" href="#输出格式规范" aria-label="Permalink to &quot;输出格式规范&quot;">​</a></h2><p><strong>文件/代码位置引用</strong>（强制）：使用反引号包裹相对路径，IDE 自动识别并渲染为可点击链接。</p><table tabindex="0"><thead><tr><th>引用对象</th><th>格式</th><th>示例</th></tr></thead><tbody><tr><td>文件</td><td><code>`相对路径`</code></td><td><code>`src/xxx.tsx`</code></td></tr><tr><td>文件+行号</td><td><code>`相对路径`</code> L行号</td><td><code>`src/xxx.tsx`</code> L42</td></tr><tr><td>目录</td><td><code>`相对目录/`</code></td><td><code>`src/utils/`</code></td></tr></tbody></table><p><strong>❌ 严禁</strong>：裸文本路径、只有文件名、裸绝对路径、Markdown 链接格式。</p><blockquote><p>📌 详细反模式表格/IDE 兼容性说明 → 按需规则 <code>按需-输出格式详细规范</code></p></blockquote><h2 id="对话质量守卫-精要" tabindex="-1">对话质量守卫（精要） <a class="header-anchor" href="#对话质量守卫-精要" aria-label="Permalink to &quot;对话质量守卫（精要）&quot;">​</a></h2><ul><li>🟡 &gt; 40 轮 / &gt; 100 工具调用 → 压缩 + 提示</li><li>🔴 &gt; 70 轮 / &gt; 180 工具调用 <strong>或</strong> 异常信号（重复提问/遗忘约束/路径混淆） → 保存进度 + 建议开新对话</li><li><strong>反过度干预</strong>：无异常信号时不打断用户工作节奏</li><li><strong>长对话收尾沉淀</strong>：dev-flow 激活 + ≥10 轮 + 用户说&quot;先到这&quot;→ 触发 <code>.flow.recovery</code> 刷新提议</li></ul><blockquote><p>📌 完整阈值/触发条件/用户回复处理/抑制规则 → <code>skills/dev-flow/references/conversation-quality.md</code></p></blockquote><h2 id="自主研究规则" tabindex="-1">自主研究规则 <a class="header-anchor" href="#自主研究规则" aria-label="Permalink to &quot;自主研究规则&quot;">​</a></h2><blockquote><p>遇到不确定或无法解决的问题时，先自行多轮搜索研究，禁止浅搜即止直接询问用户。</p></blockquote><ul><li><strong>触发</strong>：超出已有知识的领域 / 搜索一次结果不满意 / 用户问题隐含&quot;需要调研&quot;</li><li><strong>搜索范围</strong>：与项目代码相关时优先本项目（codebase_search）→ 跨项目 → 平台（搜索引擎/文档系统/知识库）；通用技术问题优先内网/外网（web_search，含 GitHub/官方文档）。最终覆盖所有来源，含可用 skills（find-skills）</li><li><strong>退出与汇报</strong>：找到可行方案后汇总汇报；多轮搜索明显无果时也及时汇报，不陷入无限搜索。汇报内容：候选方案 + 优缺点 + 推荐 + 待用户决策的卡点。方案唯一且风险明确时，仍需呈现方案并给出简要理由，等用户确认后执行</li><li><strong>红线</strong>：禁止在用户决策前执行任何方案（安装工具/修改代码/修改配置等）；禁止凭记忆猜测替代搜索验证</li></ul><h2 id="自我改进与持续学习" tabindex="-1">自我改进与持续学习 <a class="header-anchor" href="#自我改进与持续学习" aria-label="Permalink to &quot;自我改进与持续学习&quot;">​</a></h2><ul><li><strong>用户纠正</strong> → 建议用户创建规则固化（最高优先级）</li><li><strong>操作失败</strong> → 记录到工作上下文或 <code>.learnings/ERRORS.md</code></li><li><strong>同类问题 ×2</strong> → 停下分析根因；<strong>×3</strong> → 必须建议提升为规则</li><li><strong>重复模式 / 复杂任务</strong> → ≥3 次相似操作时提议封装为规则或 Skill；复杂任务前检索 <code>.learnings/</code> 和已有规则的历史经验</li></ul><blockquote><p>📌 「真的有用」高于「显得专业」祖父原则 + 派生执行规则 → 按需规则 <code>按需-自我管控-反对显得专业本能.mdc</code></p></blockquote><h2 id="持久化与维护" tabindex="-1">持久化与维护 <a class="header-anchor" href="#持久化与维护" aria-label="Permalink to &quot;持久化与维护&quot;">​</a></h2><ul><li><code>.learnings/</code> 目录<strong>必须</strong>在 <code>~/.codebuddy/.learnings/</code>，严禁在项目目录创建</li><li>经验教训优先 <code>create_rule</code> 固化，<strong>禁止 <code>update_memory</code></strong></li><li>修改规则/Skill 前<strong>必须先读取最新内容</strong>，禁止凭记忆修改</li><li>禁止擅自删除或覆盖用户已有规则内容</li><li><strong>agents/skills/rules 修改路径</strong>：一律修改 <code>~/myGithub/ai-coding-kit/</code> 源码仓库下的对应文件（<code>agents</code> → <code>ai-coding-kit/agents/</code>、<code>skills</code> → <code>ai-coding-kit/skills/</code>、<code>rules</code> → <code>ai-coding-kit/rules/</code>）；禁止修改 <code>~/.codebuddy/plugins/marketplaces/</code> 下的同步产物（改后会被覆盖）</li><li><strong>修改后的交互式提醒</strong>：详细格式见按需规则 <code>按需-交互式提醒格式规范</code></li><li><strong>修改 dev-flow 依赖 Skill/规则后</strong>：提醒用户执行 <code>package.sh</code> 同步到 dist → <code>skills/dev-flow/references/dist-sync.md</code></li><li><strong>修改 ai-coding-kit 内容后 README 同步提醒（强制）</strong>：修改本仓库任何 skill/agent/rule 后，必须主动检查并提示用户同步 README：① 该 skill 自身 <code>README.md</code>（若存在）；② 外层 <code>README.md</code> 的易过期信息（Skill 清单表格与数量、Agents/Rules 数量、安装命令数字、功能简介）</li></ul><h3 id="alwaysapply-规则文件准入评估-强制" tabindex="-1">alwaysApply 规则文件准入评估（强制） <a class="header-anchor" href="#alwaysapply-规则文件准入评估-强制" aria-label="Permalink to &quot;alwaysApply 规则文件准入评估（强制）&quot;">​</a></h3><blockquote><p>向 <code>AI行为规范.mdc</code> / <code>开发规范-红线.mdc</code> 等 alwaysApply 文件新增内容前，<strong>必须先做 5 维评估</strong>，全过才能写入。否则迁移到 skill 自身或按需规则。</p></blockquote><table tabindex="0"><thead><tr><th>维度</th><th>准入门槛</th></tr></thead><tbody><tr><td>D1 适用范围</td><td>每次对话/每次编码都适用，非特定场景专属</td></tr><tr><td>D2 原子性</td><td>1-3 行能说清「不看会出问题」的硬底线</td></tr><tr><td>D3 重复性</td><td>现有 alwaysApply 文件 + 各 skill 红牌系统<strong>未覆盖</strong>该信息</td></tr><tr><td>D4 触发位点</td><td>不依赖某个 skill 加载就能让 AI 看到（即「全局必看」），否则归 skill 自维护</td></tr><tr><td>D5 维护成本</td><td>单一权威源，逻辑变化时只改一处</td></tr></tbody></table><p><strong>任一维度不过</strong> → 降级至对应 skill 文档 / 按需规则 / <code>.learnings/</code>，用 1 行链接从此处指向。</p><h2 id="dev-flow-步骤加载文件清单严格执行-强制" tabindex="-1">dev-flow 步骤加载文件清单严格执行（强制） <a class="header-anchor" href="#dev-flow-步骤加载文件清单严格执行-强制" aria-label="Permalink to &quot;dev-flow 步骤加载文件清单严格执行（强制）&quot;">​</a></h2><ul><li>各步骤文档明确点名的 <code>read_file</code> 加载指令是<strong>强制指令</strong>，禁止用 <code>grep</code> / <code>search</code> / 凭记忆替代</li><li>每次进入 step-N 时，<strong>第一个 tool call</strong> 必须是 <code>read_file</code> 加载该步骤文档明确点名的依赖文件</li><li>简化的口播（如 H.1/H.2/H.3）是<strong>对话简称</strong>，不是流程实际边界——实际边界以被加载文档为准</li></ul><blockquote><p>📌 各步骤的具体加载清单 + 红牌强提醒 → 由 skill 自身维护（如 <code>skills/dev-flow/steps/step-7-commit.md</code> 顶部红牌 #16），本文件不做重复</p></blockquote><h2 id="文件精准定位策略" tabindex="-1">文件精准定位策略 <a class="header-anchor" href="#文件精准定位策略" aria-label="Permalink to &quot;文件精准定位策略&quot;">​</a></h2><blockquote><p>禁止凭记忆猜测文件名/路径/扩展名。<strong>先确认，再操作。</strong></p></blockquote><ul><li>不确定文件名/路径 → 先用 <code>list_dir</code> / <code>search_file</code> 确认</li><li>禁止反复猜测不同文件名调用 <code>read_file</code></li></ul><h2 id="schema-字段实现验证-reflex" tabindex="-1">Schema 字段实现验证 reflex <a class="header-anchor" href="#schema-字段实现验证-reflex" aria-label="Permalink to &quot;Schema 字段实现验证 reflex&quot;">​</a></h2><p>读到任何 skill schema 中带「枚举值」的「控制类字段」时（如 <code>trigger_step</code> / <code>phase</code> / <code>mode</code> / <code>routing_target</code>），<strong>必须先 grep 确认存在分发逻辑后才能据此向用户提供决策选项</strong>。</p><p><strong>三步验证法</strong>（精简骨架）：</p><ol><li><code>grep -rn &quot;字段名&quot; ~/.codebuddy/skills/&lt;skill&gt;/</code> 统计总出现次数</li><li><code>grep -rn &quot;字段名.*==\\|case.*字段名&quot; .../scripts .../steps</code> 统计真正读取并分支的代码</li><li><strong>若步骤 2 命中数 = 0</strong> → 该字段是「幽灵选项」，<strong>只能按主流程默认路径执行</strong>，不得给用户决策矩阵</li></ol><blockquote><p>📌 完整反例（trigger_step 事故复盘）+ 禁令清单 → 按需规则 <code>按需-Schema字段验证详细规范</code></p></blockquote><h2 id="跨项目分析-reflex-精要" tabindex="-1">跨项目分析 reflex（精要） <a class="header-anchor" href="#跨项目分析-reflex-精要" aria-label="Permalink to &quot;跨项目分析 reflex（精要）&quot;">​</a></h2><blockquote><p>分析涉及非当前 workspace 的代码时，禁止凭推测、禁止等用户提醒才去查本地。</p></blockquote><p><strong>三步法</strong>：① 本地探测工作空间目录 ② 命中则先分支感知 <code>git branch --show-current</code> → ③ 未命中则提醒用户 clone</p><p><strong>核心禁令</strong>：未做分支感知禁止读源码 / 已知本地路径禁止走 远程知识库 / 禁止静默 fallback</p><blockquote><p>📌 完整触发信号/三步法详细/来源标注/反模式清单 → <code>skills/dev-flow/references/cross-project/analysis.md</code>；Diff / Commit 查看规范 → <code>skills/dev-flow/references/cross-project/integration.md</code> §「Diff / Commit 查看规范」</p></blockquote><h2 id="workspace-外文件操作策略" tabindex="-1">Workspace 外文件操作策略 <a class="header-anchor" href="#workspace-外文件操作策略" aria-label="Permalink to &quot;Workspace 外文件操作策略&quot;">​</a></h2><blockquote><p>当 <code>~/.codebuddy/</code> 不在当前 workspace 内时，必须用终端命令操作。</p></blockquote><ol><li>备份优先（红线）：修改前必须 <code>cp</code> 到 <code>.backup/{YYYYMMDD}/</code></li><li>修改已有文件：「备份 → 写 tmp → 验证 → mv -f 原子替换」四步范式</li><li>小改动（&lt;5 行）：允许 <code>sed -i &#39;&#39;</code> 精确替换，前提是已备份</li></ol><blockquote><p>📌 完整 bash 范例和恢复流程 → 按需规则 <code>按需-workspace-外操作详解</code></p></blockquote><h2 id="验证行为规范" tabindex="-1">验证行为规范 <a class="header-anchor" href="#验证行为规范" aria-label="Permalink to &quot;验证行为规范&quot;">​</a></h2><ul><li>删除/清理后<strong>必须反向搜索</strong>所有引用，确认无残留死链接</li><li>得出&quot;不存在/已清理&quot;结论前，须用 <strong>≥2 种关键词</strong> 交叉验证</li><li>禁止先有结论再找证据</li><li><strong>承诺一致性必须 grep 实测</strong>：任何&quot;已完成/已固化&quot;类承诺，必须用工具实测验证后才能宣告完成</li></ul><blockquote><p>📌 编辑工具假性成功兜底/批量重命名三大陷阱/详细 SOP → 按需规则 <code>按需-验证行为详细规范</code></p></blockquote><h2 id="skill-模板严格遵循规则" tabindex="-1">Skill 模板严格遵循规则 <a class="header-anchor" href="#skill-模板严格遵循规则" aria-label="Permalink to &quot;Skill 模板严格遵循规则&quot;">​</a></h2><blockquote><p>调用 Skill 生成结构化文档时，<strong>必须严格遵循 Skill 内定义的模板结构</strong>，禁止自由发挥。</p></blockquote><blockquote><p>📌 详细规则（6 条）→ <code>skills/tech-doc/modules/doc-platform-doc.md</code> §「模板遵循规范」</p></blockquote><h2 id="方案确认门禁-强制" tabindex="-1">方案确认门禁（强制） <a class="header-anchor" href="#方案确认门禁-强制" aria-label="Permalink to &quot;方案确认门禁（强制）&quot;">​</a></h2><blockquote><p>AI 形成方案后须先呈现 + 等待用户明确确认，再执行。以下<strong>不算确认</strong>——补充信息、提出质疑、反问、讨论方案细节。方案有任何变更后，必须重新呈现并再次等确认。确认信号仅限：<code>可以</code> <code>开始</code> <code>做吧</code> <code>执行</code> <code>就这样</code> <code>OK</code> <code>同意</code> 等明确动作指令，或 <code>ask_followup_question</code> 中用户选择的「确认执行」选项。</p></blockquote><h2 id="全局决策交互强制规则-强制" tabindex="-1">全局决策交互强制规则（强制） <a class="header-anchor" href="#全局决策交互强制规则-强制" aria-label="Permalink to &quot;全局决策交互强制规则（强制）&quot;">​</a></h2><blockquote><p>所有需要用户决策/确认的场景，<strong>必须使用 <code>ask_followup_question</code> 工具弹出交互式选项</strong>，禁止用纯文本提问。</p></blockquote><p><strong>例外</strong>：需要用户提供<strong>开放式信息</strong>时允许纯文本提问。</p><p><strong>交互式选项一致性</strong>：表格选项与 <code>ask_followup_question</code> 选项逐条一一对应、编号一致。 <strong>推荐项一致性</strong>（2026-07-29 新增）：若文本表格某行有 <code>⭐</code> 推荐标识，则 <code>ask_followup_question</code> 对应 option 的 <code>label</code> 必须以 <code>⭐ [推荐] </code> 开头，反之亦然（传递互斥检查）。</p><blockquote><p>📌 dev-flow 中的实施细节 → <code>skills/dev-flow/steps/step-router.md</code> §「交互式决策强制规则」</p></blockquote>',77)])])}const k=e(c,[["render",r]]);export{h as __pageData,k as default};
